"use client";import { useState } from "react";import { activities,categories,categoryLabel,Festival,FestivalActivity } from "@/lib/types";import Link from "next/link";
export function SubmissionForm(){const [chosen,setChosen]=useState<FestivalActivity[]>([]),[message,setMessage]=useState(""),[saved,setSaved]=useState<Festival|undefined>();function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const d=new FormData(e.currentTarget);if(!chosen.length){setMessage("Choose at least one activity.");return}const name=String(d.get("nameEn"));const f:Festival={id:`local-${Date.now()}`,slug:name.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,""),nameEn:name,nameJa:String(d.get("nameJa")),category:String(d.get("category")) as Festival["category"],startDate:String(d.get("startDate")),endDate:String(d.get("endDate"))||undefined,startTime:String(d.get("startTime"))||undefined,endTime:String(d.get("endTime"))||undefined,prefecture:String(d.get("prefecture")),city:String(d.get("city")),venue:String(d.get("venue"))||undefined,address:String(d.get("address"))||undefined,description:String(d.get("description")),imageUrl:String(d.get("imageUrl"))||undefined,activities:chosen,participationType:String(d.get("participation")),reservationRequired:d.get("reservation")==="yes",reservationUrl:String(d.get("reservationUrl"))||undefined,price:String(d.get("price"))||undefined,paymentMethods:[String(d.get("payment"))],officialWebsite:String(d.get("website"))||undefined,organizerName:String(d.get("organizer"))||undefined,contactEmail:String(d.get("email"))||undefined,ticketUrl:String(d.get("ticket"))||undefined,rainPolicy:String(d.get("rain"))||undefined,notes:String(d.get("notes"))||undefined};const old=JSON.parse(localStorage.getItem("matsuri-submissions")||"[]") as Festival[];localStorage.setItem("matsuri-submissions",JSON.stringify([f,...old]));setSaved(f);setMessage("Your festival has been saved in this browser.");}if(saved)return <div className="notice"><h2>Festival submitted</h2><p>{message}</p><Link className="button" href={`/event/${saved.id}/${saved.slug}`}>View festival detail</Link></div>;return <form className="form" onSubmit={submit}>{message&&<p className="notice">{message}</p>}<div className="two"><label className="field">FESTIVAL NAME JAPANESE<input required name="nameJa"/></label><label className="field">FESTIVAL NAME ENGLISH<input required name="nameEn"/></label></div><div className="two"><label className="field">CATEGORY<select required name="category"><option value="">Choose category</option>{categories.map(c=><option value={c} key={c}>{categoryLabel(c)}</option>)}</select></label><label className="field">IMAGE URL<input name="imageUrl" type="url" placeholder="https://..."/></label></div><div className="two"><label className="field">START DATE<input required name="startDate" type="date"/></label><label className="field">END DATE<input name="endDate" type="date"/></label></div><div className="two"><label className="field">PREFECTURE<input required name="prefecture"/></label><label className="field">CITY<input required name="city"/></label></div><label className="field">DESCRIPTION<textarea required name="description" rows={5}/></label><fieldset><legend><b>What visitors can do / Activities</b></legend><div className="checklist">{activities.map(a=><label key={a}><input type="checkbox" onChange={e=>setChosen(e.target.checked?[...chosen,a]:chosen.filter(x=>x!==a))}/> {a}</label>)}</div></fieldset><div className="two"><label className="field">VENUE NAME<input name="venue"/></label><label className="field">ADDRESS<input name="address"/></label></div><div className="two"><label className="field">START TIME<input name="startTime" type="time"/></label><label className="field">END TIME<input name="endTime" type="time"/></label></div><div className="two"><label className="field">PARTICIPATION TYPE<select name="participation"><option>Open to everyone</option><option>Reservation required</option><option>Conditional participation</option></select></label><label className="field">RESERVATION REQUIRED<select name="reservation"><option value="no">No</option><option value="yes">Yes</option></select></label></div><div className="two"><label className="field">PRICE<input name="price"/></label><label className="field">PAYMENT METHOD<select name="payment"><option>Free</option><option>Cash</option><option>Credit Card</option><option>QR / Cashless</option><option>Other</option></select></label></div><div className="two"><label className="field">OFFICIAL WEBSITE<input name="website" type="url"/></label><label className="field">RESERVATION URL<input name="reservationUrl" type="url"/></label></div><div className="two"><label className="field">ORGANIZER NAME<input name="organizer"/></label><label className="field">CONTACT EMAIL<input name="email" type="email"/></label></div><label className="field">RAIN POLICY<select name="rain"><option>Held rain or shine</option><option>Cancelled in rain</option><option>Venue change</option><option>Check official website</option><option>Other</option></select></label><label className="field">NOTES<textarea name="notes" rows={3}/></label><button className="button">Submit festival</button></form>}
